begin;
select no_plan();
insert into auth.users(id,email,is_anonymous,raw_user_meta_data) values ('fb000000-0000-4000-8000-000000000001',null,true,'{}');
insert into private.part_one_policies(id,version,retain_allowed,display_allowed,export_allowed,permission_evidence,label_assertion_permission_evidence,label_assertion_kinds) values ('synthetic-literal-label-v1','1',true,true,false,'Synthetic local original source permission','Synthetic local reviewed claim annotation permission',array['claim']);
insert into private.part_one_records(id,kind,revision,policy_id,policy_version,payload,observed_at,expires_at) values ('fb100000-0000-4000-8000-000000000001','observation',1,'synthetic-literal-label-v1','1','{"rawText":"Glycerin\nClaim: fragrance-free","labelAssertions":[{"assertionId":"claim-1","assertionKind":"claim","text":"fragrance-free","start":16,"end":30,"transcription":"clear","conditional":null}]}',now(),now()+interval '1 day');
create temp table assertion as select jsonb_build_object('assertionId','claim-1','assertionKind','claim','text','fragrance-free','sourceTextHash',encode(extensions.digest(E'Glycerin\nClaim: fragrance-free','sha256'),'hex'),'span',jsonb_build_object('observationId','fb100000-0000-4000-8000-000000000001','sourceRevision',1,'sectionId','label:fb100000-0000-4000-8000-000000000001','entryId',null,'start',16,'end',30,'raw','fragrance-free'),'transcription','clear','conditional',null,'fieldPermission',jsonb_build_object('policyId','synthetic-literal-label-v1','policyVersion','1','assertionKind','claim','policyEpoch',0,'expiresAt',private.part_one_utc(now()+interval '1 hour'),'permitted',true)) body;
select ok(private.part_two_label_allowed((select body from assertion),'fb000000-0000-4000-8000-000000000001'),'explicit immutable literal annotation plus independent live grant qualifies');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{span,start}','17'),'fb000000-0000-4000-8000-000000000001'),'wrong UTF16 span cannot become a label fact');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{fieldPermission,policyEpoch}','99'),'fb000000-0000-4000-8000-000000000001'),'stale assertion policy epoch fails closed');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{fieldPermission,policyVersion}','"other"'),'fb000000-0000-4000-8000-000000000001'),'wrong exact source policy version fails closed');
select is(private.part_two_utf16_slice('💧fragrance-free',2,16),'fragrance-free','SQL preserves UTF16 span offsets after astral prefix');
select is(private.part_two_utf16_slice('💧fragrance-free',1,16),null,'surrogate-half start cannot fabricate source text');
select is((select label_assertion_kinds from private.part_one_policies where id='derive_catalog'),'{}'::text[],'catalog policy has no implicit label assertion permission');
insert into private.part_two_releases(id,versions,release_hash,permitted,review_evidence) values ('assertion-test-release','{}',repeat('a',64),true,'original synthetic local SQL fixture');
insert into private.part_one_scans(id,owner_id,idempotency_key,request,generation,result) values ('fb200000-0000-4000-8000-000000000001','fb000000-0000-4000-8000-000000000001','label-pins','{}',0,'{}');
insert into private.part_two_current(binding_key,owner_id,scan_id,result_revision,generation,evidence_revision,deletion_epoch,dependencies) values ('label-pin','fb000000-0000-4000-8000-000000000001','fb200000-0000-4000-8000-000000000001',2,0,1,0,array['fb100000-0000-4000-8000-000000000001'::uuid]);
insert into private.part_one_records(id,kind,item_id,revision,policy_id,policy_version,payload,dependencies,observed_at,expires_at) values ('fb400000-0000-4000-8000-000000000001','declaration','fb500000-0000-4000-8000-000000000001',1,'synthetic-literal-label-v1','1','{"observationIds":["fb100000-0000-4000-8000-000000000001"],"predicate":{"association":{"passed":true}},"structuredSections":[{"sectionId":"ingredient-literal","kind":"ingredients","rawText":"Glycerin","entries":[{"rawToken":"Glycerin","sourceSpans":[{"observationId":"fb100000-0000-4000-8000-000000000001","sourceRevision":1,"start":0,"end":8}]}]}]}',array['fb100000-0000-4000-8000-000000000001'::uuid],now(),now()+interval '1 day');
create temp table label_snapshot as select jsonb_build_object('snapshotId','interpretation-original','binding','{"kind":"declaration","declarationId":"fb400000-0000-4000-8000-000000000001","declarationRevision":1,"itemId":"fb500000-0000-4000-8000-000000000001","scope":"public","ownerId":null,"observations":[{"observationId":"fb100000-0000-4000-8000-000000000001","revision":1}]}'::jsonb,'createdAt',private.part_one_utc(now()),'versions','{"factPolicy":"attributed-positive-facts-v6","parser":"bounded-lossless-v3"}'::jsonb,'labelAssertions',jsonb_build_array((select body from assertion)),
 'dependencyManifest',jsonb_build_object('sourceRefs',jsonb_build_array(jsonb_build_object('observationId','fb100000-0000-4000-8000-000000000001','sourceRevision',1,'sourceTextHash',encode(extensions.digest(E'Glycerin\nClaim: fragrance-free','sha256'),'hex'))),'labelAssertionPermissions',jsonb_build_array((select body->'fieldPermission'||jsonb_build_object('assertionId','claim-1') from assertion)),'dictionaryRecordIds','[]'::jsonb,'withdrawnExplanationDependencies','[]'::jsonb,'explanationPolicies','[]'::jsonb),
 'facts',jsonb_build_array('{"kind":"declared_ingredient","factId":"unchanged-ingredient","value":{"rawName":"Glycerin"},"dictionaryDependencies":[]}'::jsonb,jsonb_build_object('kind','product_label_assertion','factId','withdraw-label','occurrenceId','claim-1','subject','{"kind":"bound_label_assertion","assertionId":"claim-1","declarationId":"fb400000-0000-4000-8000-000000000001","declarationRevision":1}'::jsonb,'value','{"text":"fragrance-free","assertionKind":"claim","attribution":"label_says"}'::jsonb,'spans',jsonb_build_array((select body->'span' from assertion)),'sourceDependencies','["fb100000-0000-4000-8000-000000000001"]'::jsonb,'dictionaryDependencies','[]'::jsonb,'limitations','["label_claim_not_verified","no_ingredient_absence_inference"]'::jsonb))) body;
insert into private.part_two_snapshots(id,binding_key,owner_id,build_key,result_revision,release_id,payload,dependencies,private_payload,expires_at) select 'fb300000-0000-4000-8000-000000000001','label-pin','fb000000-0000-4000-8000-000000000001','label-original',2,'assertion-test-release',jsonb_build_object('state','ready','resultRevision',2,'output',jsonb_build_object('kind','bound','reading',body,'productFacts',body)),array['fb100000-0000-4000-8000-000000000001'::uuid],false,now()+interval '1 hour' from label_snapshot;

select ok(not has_function_privilege('authenticated','public.part_two_resolve(uuid,jsonb)','execute'),'customer cannot call full-context resolver even with a forged owner');
select ok(not has_function_privilege('anon','public.part_two_resolve(uuid,jsonb)','execute'),'anonymous role cannot call full-context resolver');
select ok(has_function_privilege('service_role','public.part_two_resolve(uuid,jsonb)','execute'),'verified server role owns validation input resolution');
set local role authenticated;
select set_config('request.jwt.claim.sub','fb000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.part_two_operation('resolve','{}')$$,'42501','PART_TWO_SERVER_RESOLVE_ONLY','old customer resolve rejects without context or ticket');
reset role;
select ok(not private.part_two_label_allowed((select body||jsonb_build_object('sourceText',E'Glycerin\nClaim: fragrance-free') from assertion),'fb000000-0000-4000-8000-000000000001'),'publication rejects full-source client root');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{sourceTextHash}',to_jsonb(repeat('0',64))),'fb000000-0000-4000-8000-000000000001'),'foreign source text hash cannot authorize projected literal');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{span,sectionId}','"Apply nightly"'),'fb000000-0000-4000-8000-000000000001'),'canonical source section cannot be raw-text sink');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{conditional}','"Apply nightly"'),'fb000000-0000-4000-8000-000000000001'),'raw conditional metadata cannot enter client root');
create temp table literal as select '{"sectionId":"ingredient-literal","kind":"ingredients","rawText":"Glycerin","sourceOffset":0,"observationId":"fb100000-0000-4000-8000-000000000001","sourceRevision":1}'::jsonb body;
select is(private.part_two_current_literal((select body from literal),(select body from label_snapshot),'fb000000-0000-4000-8000-000000000001'),(select body from literal),'literal is exactly derived from selected immutable declaration');
select ok(not private.part_two_literal_snapshot_allowed((select body||jsonb_build_object('literalSections',jsonb_build_array(jsonb_set((select body from literal),'{rawText}',to_jsonb(E'Glycerin\nClaim: fragrance-free'::text)))) from label_snapshot),'fb000000-0000-4000-8000-000000000001'),'legitimate rawText key cannot substitute full label source');
create temp table legacy_root as select (body-'sourceTextHash')||jsonb_build_object('sourceText',E'Glycerin\nClaim: fragrance-free','unknownRaw','DENIED_USAGE_apply_nightly') body from assertion;
select is(private.part_two_current_label_root((select body from legacy_root),'fb000000-0000-4000-8000-000000000001'),(select body from assertion),'legacy full-source root verifies originals then selects only approved client fields');
create temp table legacy as select jsonb_set(payload,'{output,reading,labelAssertions}',jsonb_build_array((select body from legacy_root))) payload from private.part_two_snapshots where id='fb300000-0000-4000-8000-000000000001';
update legacy set payload=jsonb_set(payload,'{output,productFacts,labelAssertions}',jsonb_build_array((select body from legacy_root)));
update legacy set payload=payload||'{"sourceText":"DENIED_USAGE_apply_nightly","permittedText":{"sections":[{"text":"DENIED_USAGE_apply_nightly"}]}}';
update legacy set payload=jsonb_set(payload,'{output}',(payload->'output')||'{"sourceText":"DENIED_USAGE_apply_nightly"}');
update legacy set payload=jsonb_set(payload,'{output,reading,literalSections}',jsonb_build_array((select body||'{"sourceText":"DENIED_USAGE_apply_nightly"}' from literal)));
update legacy set payload=jsonb_set(payload,'{output,productFacts,literalSections}',jsonb_build_array(jsonb_set((select body from literal),'{rawText}',to_jsonb(E'Glycerin\nClaim: fragrance-free'::text))));
update legacy set payload=jsonb_set(payload,'{output,reading,dependencyManifest}',(payload#>'{output,reading,dependencyManifest}')||'{"sourceText":"DENIED_USAGE_apply_nightly"}');
update legacy set payload=jsonb_set(payload,'{output,reading,dependencyManifest,sourceRefs,0}',(payload#>'{output,reading,dependencyManifest,sourceRefs,0}')||'{"sourceText":"DENIED_USAGE_apply_nightly"}');
update legacy set payload=jsonb_set(payload,'{output,reading,dependencyManifest,labelAssertionPermissions,0}',(payload#>'{output,reading,dependencyManifest,labelAssertionPermissions,0}')||'{"sourceText":"DENIED_USAGE_apply_nightly"}');
update legacy set payload=jsonb_set(payload,'{output,reading,facts,0,value}',(payload#>'{output,reading,facts,0,value}')||'{"sourceText":"DENIED_USAGE_apply_nightly"}');
select ok(not private.part_two_client_result_containers((select payload from legacy)),'all legacy extra containers and ready permittedText are rejected at publication');
insert into private.part_two_snapshots(id,binding_key,owner_id,build_key,result_revision,release_id,payload,dependencies,private_payload,expires_at) select 'fb300000-0000-4000-8000-000000000002',binding_key,owner_id,'unsafe-legacy',3,release_id,(select payload from legacy),dependencies,private_payload,expires_at from private.part_two_snapshots where id='fb300000-0000-4000-8000-000000000001';
insert into private.part_one_saves(id,owner_id,idempotency_key,scan_id,snapshot_at_save_id,saved_result,saved_request) values('fb700000-0000-4000-8000-000000000001','fb000000-0000-4000-8000-000000000001','legacy-byte-read','fb200000-0000-4000-8000-000000000001','fb400000-0000-4000-8000-000000000001','{}','{}');
insert into private.part_two_saves(save_id,owner_id,snapshot_id,binding_key,result_revision,snapshot_at_save_id,saved_versions) values('fb700000-0000-4000-8000-000000000001','fb000000-0000-4000-8000-000000000001','fb300000-0000-4000-8000-000000000002','label-pin',3,'fb300000-0000-4000-8000-000000000002','{}');
set local role authenticated;
select set_config('request.jwt.claim.sub','fb000000-0000-4000-8000-000000000001',true);
create temp table projected as select public.part_two_operation('saves/read','{"saveId":"fb700000-0000-4000-8000-000000000001"}')->'result' body;
reset role;
select ok(not (select body::text like '%DENIED_USAGE_apply_nightly%' from projected),'legacy ready/result/output/manifest/pin/value/literal extras are all purged');
select ok(not (select body::text like '%"sourceText":%' from projected),'client projection contains no full sourceText key at any tested layer');
select is((select body#>'{output,productFacts,literalSections}' from projected),jsonb_build_array((select body from literal)),'saved projection restores exact original ingredient literal instead of full label text');
select is((select body#>'{output,productFacts,facts}' from projected),(select body->'facts' from label_snapshot),'permitted claim and independent ingredient IDs/text/authority remain identical');
select is((select body#>'{output,reading,versions}' from projected),(select body->'versions' from label_snapshot),'historical interpretation releases remain pinned');
select ok((select (body->>'resultRevision')::integer from projected)>3,'legacy sanitation allocates a new immutable monotonic revision without field grant change');
select ok(private.part_two_client_result_containers((select body from projected)),'sanitized saved result has finite allowed containers');
select is((select count(*)::integer from private.part_two_snapshots where id='fb300000-0000-4000-8000-000000000002'),0,'unsafe legacy copied snapshot bytes are purged');
-- Source annotations remain server-only; a raw non-null conditional is emitted as a fixed marker.
insert into private.part_one_records(id,kind,revision,policy_id,policy_version,payload,observed_at,expires_at) values ('fb100000-0000-4000-8000-000000000002','observation',1,'synthetic-literal-label-v1','1','{"rawText":"fragrance-free","labelAssertions":[{"assertionId":"conditional-claim","assertionKind":"claim","text":"fragrance-free","start":0,"end":14,"transcription":"clear","conditional":"DENIED_USAGE_apply_nightly"}]}',now(),now()+interval '1 day');
create temp table conditional_root as select jsonb_set(jsonb_set(jsonb_set(jsonb_set((body-'sourceTextHash')||'{"sourceText":"fragrance-free","assertionId":"conditional-claim","conditional":"DENIED_USAGE_apply_nightly"}','{span,observationId}','"fb100000-0000-4000-8000-000000000002"'),'{span,sectionId}','"legacy-source"'),'{span,start}','0'),'{span,end}','14') body from assertion;
select is(private.part_two_current_label_root((select body from conditional_root),'fb000000-0000-4000-8000-000000000001')->>'conditional','conditional','legacy raw conditional is verified and replaced by fixed marker');
select ok(private.part_two_current_label_root((select body from conditional_root),'fb000000-0000-4000-8000-000000000001')::text not like '%DENIED_USAGE_apply_nightly%','legacy conditional projection cannot leak withdrawn text');
select is(private.part_two_literal_slice(repeat('a',3000),0,3000),repeat('a',3000),'ingredient literal authority remains bounded but is not limited to the shorter assertion-card text cap');
select is(public.part_two_operation('saves/read','{"saveId":"fb700000-0000-4000-8000-000000000001"}')->'result',(select body from projected),'direct historical replay remains byte-safe and identical after immutable projection');
select finish();
rollback;
